def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the horizontal repeat period from the unobscured right side.
    period = 5
    for p in range(2, 11):
        comparisons = 0
        valid = True
        for r in range(3, h):
            for c in range(18, w - p):
                a, b = grid[r][c], grid[r][c + p]
                if a != 0 and b != 0:
                    comparisons += 1
                    if a != b:
                        valid = False
                        break
            if not valid:
                break
        if valid and comparisons >= 15:
            period = p
            break

    for r in range(h):
        if r < 2:
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = 1
            continue

        if r == 2:
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = 1 if c < 2 else 4
            continue

        # The outer background and the frame along the top and left.
        for c in range(min(2, w)):
            if out[r][c] == 0:
                out[r][c] = 1
        if w > 2 and out[r][2] == 0:
            out[r][2] = 4

        # Learn this row's repeating pattern from unmasked cells.
        by_residue = {}
        for c in range(8, w):
            value = grid[r][c]
            if value != 0:
                by_residue.setdefault(c % period, []).append(value)

        pattern = {}
        for residue, values in by_residue.items():
            pattern[residue] = max(set(values), key=values.count)

        for c in range(3, w):
            if out[r][c] == 0:
                if c % period in pattern:
                    out[r][c] = pattern[c % period]

    return out
